var draw = SVG().addTo('#container').size('100%', '100%');
draw.viewbox(0, 0, 1220, 560);

/* ── geometry & style constants ─────────────────────────────────────── */
var AXIS_Y = 320, AMP = 132, AMP_M = 190, T_MIN = -3, T_MAX = 7;
var MT_MIN = -5, MT_MAX = 5;             // wider kernel window: more sidelobes
var BLUE = '#1e1ef0', GREEN = '#2ee62e', RED = '#f40000', GRAY = '#8a8a8a';
var SERIF = "'Times New Roman', Georgia, serif";
var NYQUIST = 1.5; // π / ω_max of the underlying signal (≈1.496)

var Ts = 1, showCopies = true;
var sweepState = 'idle', sweepIdx = -1, sweepTimer = null;

/* ── layered groups ─────────────────────────────────────────────────── */
var gTrue   = draw.group(); // gray true signal (aliasing reference)
var gCopies = draw.group(); // dashed sinc copies (+ solid current copy)
var gRecon  = draw.group(); // red reconstruction
var gMid    = draw.group(); // middle-panel sinc kernel
var gStatic = draw.group(); // axes, ∘, =
var gLeft   = draw.group(); // left sample train + tick labels
var gRight  = draw.group(); // right sample train
var gText   = draw.group(); // top-most static labels

/* ── math ───────────────────────────────────────────────────────────── */
function sinc(u) { return u === 0 ? 1 : Math.sin(Math.PI * u) / (Math.PI * u); }
function f(t) { return 0.7 * Math.cos(0.9 * t + 0.4) + 0.35 * Math.cos(2.1 * t - 1.0); }
function lpx(t) { return 48 + (t - T_MIN) / (T_MAX - T_MIN) * 360; }
function mpx(t) { return 486 + (t - MT_MIN) / (MT_MAX - MT_MIN) * 230; }
function rpx(t) { return 792 + (t - T_MIN) / (T_MAX - T_MIN) * 388; }
function py(v)  { return AXIS_Y - v * AMP; }
function pym(v) { return AXIS_Y - v * AMP_M; }
function samplesList() {
  var arr = [];
  var n0 = Math.ceil((T_MIN + 0.06) / Ts), n1 = Math.floor((T_MAX - 0.06) / Ts);
  for (var n = n0; n <= n1; n++) { var t = n * Ts; arr.push({ n: n, t: t, v: f(t) }); }
  return arr;
}

/* ── drawing helpers ────────────────────────────────────────────────── */
function arrow(g, x, y0, y1, color, w, hs, op) {
  var a = g.group();
  if (op != null && op < 1) a.attr('opacity', op);
  var dir = y1 >= y0 ? 1 : -1;
  a.line(x, y0, x, y1 - dir * hs * 0.85).stroke({ color: color, width: w });
  a.polygon([[x, y1], [x - hs * 0.42, y1 - dir * hs], [x + hs * 0.42, y1 - dir * hs]]).fill(color);
  return a;
}
function hAxis(g, x1, x2, y) {
  g.line(x1, y, x2 - 15, y).stroke({ color: '#111', width: 4 });
  g.polygon([[x2, y], [x2 - 16, y - 7], [x2 - 16, y + 7]]).fill('#111');
}
function vAxis(g, x, yTop, yBot) {
  g.line(x, yBot, x, yTop + 15).stroke({ color: '#111', width: 4 });
  g.polygon([[x, yTop], [x - 7, yTop + 16], [x + 7, yTop + 16]]).fill('#111');
}
function serifTxt(g, build, x, y, size, anchor, halo) {
  var t = g.text(build).attr({
    'font-family': SERIF, 'font-size': size, 'text-anchor': anchor || 'middle', x: x, y: y
  });
  if (halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}

/* ── static picture: axes, ∘, =, labels ─────────────────────────────── */
hAxis(gStatic, 42, 420, AXIS_Y);
hAxis(gStatic, 480, 728, AXIS_Y);
vAxis(gStatic, mpx(0), 84, AXIS_Y + 40);
hAxis(gStatic, 788, 1196, AXIS_Y);

var circ = gStatic.circle(26).center(455, AXIS_Y).fill('#fff').stroke({ color: '#111', width: 4.5 });
circ.css('cursor', 'pointer');
circ.on('mousemove', function (e) { showTooltip('convolution with the kernel', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Convolution', 'Convolving the sample train with the kernel places one copy of the kernel at every sample instant, scaled by that sample\u2019s value, and adds them all together.'); });

serifTxt(gStatic, function (a) { a.tspan('='); }, 768, AXIS_Y + 16, 46);
serifTxt(gText, function (a) { a.tspan('t').attr('font-style', 'italic'); }, 430, AXIS_Y + 32, 26, 'start', true);
serifTxt(gText, function (a) { a.tspan('t').attr('font-style', 'italic'); }, 736, AXIS_Y + 32, 26, 'start', true);
serifTxt(gText, function (a) { a.tspan('t').attr('font-style', 'italic'); }, 1204, AXIS_Y + 32, 26, 'start', true);
serifTxt(gText, function (a) { a.tspan('1'); }, mpx(0) - 12, 140, 30, 'end', true);

/* ── tick labels (adaptive: drop labels when spacing gets tight) ────── */
var IT = { 'font-style': 'italic' };
var SUB = { 'font-style': 'italic', 'font-size': 15, dy: 5 };
function tickLabel(tWorld, parts) {
  if (tWorld < T_MIN + 0.15 || tWorld > T_MAX - 0.15) return;
  serifTxt(gLeft, function (add) {
    for (var i = 0; i < parts.length; i++) add.tspan(parts[i][0]).attr(parts[i][1] || {});
  }, lpx(tWorld), AXIS_Y + 44, 23, 'middle', true);
}
function renderTicks() {
  // Pixel spacing between adjacent Ts multiples; label a subset when tight.
  var pxPerTs = Ts / (T_MAX - T_MIN) * 360;
  tickLabel(0, [['0']]);
