      var a = arrow(gLeft, lpx(sm.t), AXIS_Y, py(sm.v), BLUE, 4, 13, 1);
      a.css('cursor', 'pointer');
      a.on('mousemove', function (e) { showTooltip('sample x[' + sm.n + '] = ' + sm.v.toFixed(2), e); })
       .on('mouseleave', hideTooltip)
       .on('click', function () { showPopup('Discrete samples', 'Each blue arrow is one measured value, x[n] = x(n\u00B7T_s). Reconstruction replaces every arrow with a sinc copy scaled to that height, then sums them all.'); });
    })(S[k]);
  }
